  function kvVerb(v) { var lo = v.toLowerCase(); if (KV_IRR[lo]) return KV_IRR[lo]; if (/es$/.test(lo)) return v.slice(0, -1); if (/(is|ts|ds)$/.test(lo)) return v.slice(0, -1) + (/is$/.test(lo) ? "t" : ""); if (/x$/.test(lo)) return v.slice(0, -1) + "t"; return v; }
