    if (!r.res) { if (i >= 0) S.matches.splice(i, 1); delete r.twin; return; }
    if (r.twin && S.matches.some(function (m) { return m.id === r.twin; })) return; // déjà dans ton palmarès
    var o = pool ? r : (r.opp || {}); if (!o.rank && !pool) { var A0 = trAlt(r); if (A0) o = A0.fav; }
    if (!o.rank) return;
