  // 3.44.2 : « le vainqueur de A / B » : dès que leur match est sur Ten'Up, le tour se met à jour tout seul
  function trInvScore(sc) { return String(sc || "").replace(/(\d{1,2})\s*([-\/])\s*(\d{1,2})/g, function (_, a, sep, b) { return b + "-" + a; }); }
