    if (!row) return false;
    var win = row.result === "V" ? x : other, lose = win === x ? other : x;
    r.opp = { name: win.name || "", rank: win.rank || "", club: win.club || "", tid: win.tid || "", hit: win.hit || null };
    r.beat = { name: lose.name || "", score: win === x ? row.score || "" : trInvScore(row.score) };
    r.altWas = r.alt; r.alt = null;
