    items.sort(function (a, b) { return a.when - b.when || (a.kind === "today" ? -1 : 0); });
    // dans les temps ?
    var span = Math.max(1, by - E.parseDate(g.at)), done = Math.min(1, Math.max(0, (t - E.parseDate(g.at)) / span));
    var expectNow = g.from + (g.rank - g.from) * done, have = p.status === "montee" ? p.projected : cur;
    var state = have >= expectNow + 0.5 ? "en avance" : have >= Math.floor(expectNow + 0.001) ? "dans les temps" : "en retard";
