    if (D.few) { if (me > hi) f.pro.push({ t: plural(me - hi, "échelon") + " d'avance", w: 10 }); else if (hi > me) f.con.push({ t: plural(hi - me, "échelon") + " au-dessus de toi", w: 10 }); }
    var wp = f.pro.reduce(function (a, x) { return a + x.w; }, 0), wc = f.con.reduce(function (a, x) { return a + x.w; }, 0), tot = wp + wc;
