    return s + '<div class="ff-tug">' + (pc ? '<i class="g" style="width:' + pc + '%"></i>' : "") + (100 - pc ? '<i class="t" style="width:' + (100 - pc) + '%"></i>' : "") + '</div><div class="ff-tugl"><span class="me">' + plural(f.pro.length, "point") + " pour toi</span><span class=\"him\">" + plural(f.con.length, "point") + " pour lui</span></div>" +
      '<span class="p"><b>' + head + "</b></span>" + ffPointsList(f) + "</div>";
