    var R = mmReplay(L), sc = mmScore(R) + (R.tb ? (R.sets.length ? " " : "") + R.tb.p[0] + "-" + R.tb.p[1] : R.cur[0] + R.cur[1] ? (R.sets.length ? " " : "") + R.cur[0] + "-" + R.cur[1] : "");
