      var L = S.mmLive, c = document.getElementById("mm-clock"), pc = document.getElementById("mm-pill-clock");
      if ((!c && !pc) || !L || !L.t0) { clearInterval(mmTick); mmTick = null; return; }
      if (pc && !L.t1) pc.textContent = mmClock(Date.now() - L.t0);
