    return [].concat((S.trainings || []).filter(function (t) { return t.date && t.feel == null && !t.feelSkip && t.date >= lim; }).map(function (t) { return { t: "t", o: t }; }))
      .sort(function (a, b) { return a.o.date < b.o.date ? 1 : a.o.date > b.o.date ? -1 : 0; });
