    // marge de 10 px : l'écran glisse légèrement à chaque rendu (animation d'entrée)
    nav.classList.toggle("stuck", nav.getBoundingClientRect().top <= (parseFloat(getComputedStyle(nav).top) || 0) + 10 && window.scrollY > 20);
    var top = nav.getBoundingClientRect().bottom + 12, cur = null;
    Array.prototype.forEach.call(document.querySelectorAll(".cb-a, #cb-more"), function (el) { if (el.getBoundingClientRect().top <= top + 40) cur = el.closest("#cb-more") ? "more" : el.id.slice(3); });
    var bs = nav.querySelectorAll("button"); if (!cur && bs[0]) cur = bs[0].dataset.v;
    if (window.scrollY + window.innerHeight >= document.documentElement.scrollHeight - 4 && bs.length) cur = bs[bs.length - 1].dataset.v; // en bas de page : la dernière
    Array.prototype.forEach.call(bs, function (b) { var on = b.dataset.v === cur; if (on && !b.classList.contains("on")) { b.classList.add("on"); var l = b.offsetLeft - 16; nav.scrollTo({ left: Math.max(0, l), behavior: now === true ? "auto" : "smooth" }); } else if (!on) b.classList.remove("on"); });
