    if (!S.tenup.linked || S.tenup.expired) { UI.anErr = UI.anErr || {}; UI.anErr[m.id] = "NOTU"; if (!quiet && route() === "match/" + m.id) render(); return Promise.resolve(); } // 3.57 (audit parcours P7) : jamais cherché, pas « introuvable »
