      var col = d >= 4 ? "var(--gazon)" : d <= -4 ? "var(--terre)" : "var(--muted)"; if (d >= 4) up.push(k[0]); if (d <= -4) dn.push(k[0]);
      var lo = Math.min.apply(null, pts.map(function (p0) { return p0.v; })) - 5, hi = Math.max.apply(null, pts.map(function (p0) { return p0.v; })) + 5, W = 160, H = 28;
