        hs.forEach(function (x, i) { if (i % 2 === 1 || i === hs.length - 1) g += '<text x="' + X(i).toFixed(1) + '" y="' + (H - 6) + '" text-anchor="middle" class="rw-t">' + MOIS[x.d.getMonth()].replace(/\.$/, "") + "</text>"; });
        var ln = hs.map(function (x, i) { return x.v == null ? null : X(i).toFixed(1) + "," + Y(x.v).toFixed(1); }).filter(Boolean).join(" ");
        var li = hs.length - 1; while (li > 0 && hs[li].v == null) li--;
