    if (eq && n(eq) >= 3) { var re = eq.v - exp(eq) * n(eq); L.push({ w: 1, ic: "=", c: "var(--bleu3)", t: "Ton classement (" + lab(cur) + ") : " + eq.v + " sur " + n(eq), s: re >= 1 ? "Mieux que la moyenne : tu as le niveau." : re <= -1 ? "Un peu en dessous de la moyenne." : "Dans la norme." }); }
