    playEvents(r.id).forEach(function (e) { tot += e.min; });
    if (ms.length || tot) s += '<div class="card rf-with"><b class="mt-h">Avec elle</b><div class="rf-tiles">' +
      [[String(ms.length), ms.length > 1 ? "matchs" : "match"], [v + " V", ms.length ? Math.round(v * 100 / ms.length) + " %" : "—"], [fmtHours(tot), "de jeu"]].map(function (x) { return "<span><b>" + x[0] + "</b><small>" + x[1] + "</small></span>"; }).join("") + "</div></div>";
    s += '<div class="list rf-more"><a class="row" href="#/raquette/' + r.id + '/look"><span class="grow"><span class="t">Nom et apparence</span></span><span class="muted">' + esc(r.name) + "</span>" + I.next + "</a>" +
      (r.archived ? "" : '<button class="row" data-a="rkMain" data-id="' + r.id + '"><span class="grow"><span class="t">Raquette principale</span><span class="s">Celle comptée par défaut quand tu n\'en choisis pas</span></span><span class="muted">' + (r.main ? "Oui" : "Non") + "</span></button>") + "</div>";
