    saveMatch: function () {
      var m = UI.draft;
      if (m.wo) m.minutes = null;
      if (!m.oppRank) return toast("Indique le classement de l'adversaire.");
      if (!m.date && m.source !== "tenup-pdf") return toast("Indique la date du match.");
      var clean = Object.assign({}, m); delete clean._for; delete clean._tuName; delete clean._tuInfo; delete clean.sets; delete clean._auto; delete clean._wid;
      if (S.matches.some(function (x) { return x.id === clean.id; })) clean.noted = true; // 3.60.1 : enregistrer un match déjà là = il est annoté
      if (m._wid) S.watchIn = (S.watchIn || []).filter(function (x) { return x.wid !== m._wid; });
      var i = S.matches.findIndex(function (x) { return x.id === clean.id; });
      // 3.57 (audit parcours P3) : un vrai match saisi pendant l'exemple efface l'exemple (avant : il se mélangeait aux matchs d'Alex)
      var wasDemo = false;
      if (S.demo && i < 0) { wasDemo = demoPurge(); if (/^r[12]$/.test(clean.racketId || "")) { clean.racketId = ""; clean.string = ""; clean.tension = null; } }
      // 3.47 (retour testeur : doublons) : un nouveau match qui ressemble à un match déjà là (même adversaire, à un jour près)
      if (i < 0 && clean.opp && !isAnon(clean.opp) && clean.date) {
        var tw = S.matches.filter(function (x) { return x.date && Math.abs(E.parseDate(x.date) - E.parseDate(clean.date)) <= 864e5 && x.opp && samePerson(x.opp, clean.opp); })[0];
        if (tw && !askOk("Tu as déjà un match contre " + nameCase(tw.opp) + " le " + fdate(tw.date).replace(/\.$/, "") + (tw.score ? " (" + tw.score + ")" : "") + ". L'enregistrer quand même ?")) return;
      }
      // Adversaire anonyme sur Ten'Up renommé : on garde la version Ten'Up pour reconnaître le match aux synchros
      if (i >= 0 && clean.source === "tenup" && clean.oppTenup == null && isAnon(S.matches[i].opp) && !isAnon(clean.opp)) clean.oppTenup = S.matches[i].opp;
      if (i >= 0 && clean.oppTenup != null && isAnon(clean.opp)) { clean.opp = clean.oppTenup; delete clean.oppTenup; }
      delete clean.tourSet;
      if (i < 0 && clean.tour && !/^tr/.test(clean.id)) { try { tourLink(clean); } catch (e) {} }
      if (!clean.tour) delete clean.tour;
      var c0 = null; if (i < 0 && !clean.wo && (clean.result === "V" || clean.result === "D")) { try { c0 = ctx(); } catch (e) {} }
      if (i >= 0) S.matches[i] = clean; else S.matches.push(clean);
      // Nouveau match saisi : analyse mise en avant sur l'accueil, palmarès de l'adversaire lu en silence
      // 3.42.1 : plus de carte « l'analyse » sur l'accueil : on ouvre directement la fiche du match (analyse, ressenti, plan)
      if (i < 0 && (clean.result === "V" || clean.result === "D") && !clean.wo) { setTimeout(function () { anFetch(clean, true).then(function () { if (route() === "match/" + clean.id) render(); }); }, 300); }
      if (clean.hid) hcDone(clean.hid, "match");
      var only = {}; only[clean.id] = 1; var merged = i < 0 && !clean.hid ? hcMerge(only) : 0;
      S.onboarded = true; save(); UI.draft = null;
      var imp = c0 ? impactMsg(c0, clean) : "";
      if (!merged && i < 0 && (clean.result === "V" || clean.result === "D") && !clean.wo && setsTb(clean.score).length) matchMoment(clean, c0); else
      if (merged) hcMergeToast(merged); else if (imp) toast(imp); else
      toast(!clean.racketId && !clean.wo ? "Enregistré. Choisis une raquette pour qu'il ne soit plus « à annoter »." : i >= 0 ? "Match mis à jour." : jk("s-greffe", true) ? "Match ajouté. Le greffier, c'est moi." : "Match ajouté.");
      if (i >= 0) { UI.mEdit = false; UI.annEdit = false; UI.draft = null; render(); window.scrollTo(0, 0); return; } // 3.42.1 : on reste sur la fiche
      // La fiche du match remplace le formulaire : le retour ramène là d'où tu venais, pas au formulaire vide
      if (stack[stack.length - 1] === "match/new") stack.pop();
      if (wasDemo && !S.profile.rank) { UI.afterProfil = "match/" + clean.id; toast("Ton match est gardé, l'exemple est effacé. Indique ton classement pour voir ce qu'il te rapporte."); go("profil"); window.scrollTo(0, 0); return; }
      go("match/" + clean.id); window.scrollTo(0, 0);
    },
